// Mission Deck - prototype "Demo - how we work with Mission Deck" (index.tsx)
//
// GENERATED by scripts/demo-export.js from templates/prototype/demo-export/
// (the server takes no part in it; the script substitutes {{PROTO_SLUG}}). Do
// not edit this file in the prototype directory - change demo/ in the Mission
// Deck repo and run the export again.
//
// The demo is the static page assets/demo__index.html (the same as /demo/ in
// the app, with its references rewritten to the flat assets/ directory). The
// prototype renders it in ONE frame from the same origin: its own document, its
// own keys, its own hash. Demo states = versions of the demo (demo/tracks.mjs).

import { useEffect, useRef } from 'react';
import './styles.css';
import { useDemoState, type DemoStateDef } from '../_shared/demo-state';

// A local cast, not `declare global`: several prototypes in the shell declare
// Window.amplitude with different shapes, and tsc -b compiles them together
// (TS2717). The wrapper adds no declaration of its own to that conflict.
type AmplitudeWindow = Window & { amplitude?: { track: (event: string, props?: Record<string, unknown>) => void } };

export const breakpoints = [1280, 1920];

// The demo has its own controls (Short / Full, Presentation / Walkthrough) in its
// bottom bar, so the viewer's width presets and "Demo states" toolbar are hidden
// and the frame fills the whole window. Shell contract: BreakpointViewer reads
// `viewerToolbar` (same pattern as proto-335e27850771).
export const viewerToolbar = false;

export const demoStates: DemoStateDef[] = [
  { id: 'full', label: 'Full version (every chapter)', group: 'Demo version' },
  { id: 'short', label: 'Short version (selected chapters)', group: 'Demo version' },
];

const PAGE = '/proto-assets/{{PROTO_SLUG}}/demo__index.html';

// A bare `#<track>` opens the track's first step (demo/tracks.mjs).
const TRACK_HASH: Record<string, string> = { 'full': '#full', 'short': '#short' };

export default function DemoCockpitPrototype() {
  const demoState = useDemoState(demoStates, 'full');
  const frameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    (window as AmplitudeWindow).amplitude?.track('Demo Opened', { track: demoState });
  }, [demoState]);

  // The demo listens for keys on its own window: the frame needs focus. The
  // frame is re-created per state (key), so the handler is a prop, not a
  // listener added once.
  const focusFrame = () => frameRef.current?.contentWindow?.focus();

  return (
    <div className="proto-demo-cockpit">
      <iframe
        ref={frameRef}
        key={demoState}
        className="proto-demo-cockpit-frame"
        src={PAGE + (TRACK_HASH[demoState] || TRACK_HASH['full'])}
        title="Demo — how we work with Mission Deck"
        allow="fullscreen"
        onLoad={focusFrame}
      />
    </div>
  );
}
